package store

import (
	"database/sql"
	"encoding/json"
	"errors"
)

// PageWebhook is an address that gets the events of a status page (incident
// updates, status changes) as signed JSON POST requests.
type PageWebhook struct {
	ID     int64  `json:"id"`
	PageID int64  `json:"page_id"`
	URL    string `json:"url"`
	// Secret signs every request (HMAC-SHA256), so the receiver can check
	// it comes from this hub. Generated by the hub when empty.
	Secret string `json:"secret"`
	// Events picks what is sent, empty = every event.
	Events    []string `json:"events"`
	Enabled   bool     `json:"enabled"`
	CreatedAt int64    `json:"created_at"`
	// Result of the latest delivery: when (0 = never), the HTTP status
	// (0 = no answer) and the error, "" when it worked.
	LastAt     int64  `json:"last_at"`
	LastStatus int    `json:"last_status"`
	LastError  string `json:"last_error"`
}

const pageWebhookCols = `id, page_id, url, secret, events, enabled, created_at, last_at, last_status, last_error`

func scanPageWebhook(sc interface{ Scan(...any) error }) (*PageWebhook, error) {
	w := &PageWebhook{}
	var events string
	var enabled int
	err := sc.Scan(&w.ID, &w.PageID, &w.URL, &w.Secret, &events, &enabled, &w.CreatedAt, &w.LastAt, &w.LastStatus, &w.LastError)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, ErrNotFound
	}
	if err != nil {
		return nil, err
	}
	w.Enabled = enabled != 0
	w.Events = []string{}
	if events != "" {
		_ = json.Unmarshal([]byte(events), &w.Events)
	}
	return w, nil
}

func eventsText(events []string) string {
	if len(events) == 0 {
		return ""
	}
	b, _ := json.Marshal(events)
	return string(b)
}

// PageWebhooks lists the webhooks of a page, oldest first.
func (s *Store) PageWebhooks(pageID int64) ([]*PageWebhook, error) {
	rows, err := s.db.Query(`SELECT `+pageWebhookCols+` FROM page_webhooks WHERE page_id = ? ORDER BY id`, pageID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := []*PageWebhook{}
	for rows.Next() {
		w, err := scanPageWebhook(rows)
		if err != nil {
			return nil, err
		}
		out = append(out, w)
	}
	return out, rows.Err()
}

// PagesWithWebhooks returns the ids of the pages that have at least one
// enabled webhook.
func (s *Store) PagesWithWebhooks() ([]int64, error) {
	rows, err := s.db.Query(`SELECT DISTINCT page_id FROM page_webhooks WHERE enabled = 1 ORDER BY page_id`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := []int64{}
	for rows.Next() {
		var id int64
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		out = append(out, id)
	}
	return out, rows.Err()
}

// PageWebhook returns one webhook of a page.
func (s *Store) PageWebhook(pageID, id int64) (*PageWebhook, error) {
	return scanPageWebhook(s.db.QueryRow(`SELECT `+pageWebhookCols+` FROM page_webhooks WHERE id = ? AND page_id = ?`, id, pageID))
}

// CountPageWebhooks counts the webhooks of a page.
func (s *Store) CountPageWebhooks(pageID int64) (int, error) {
	var n int
	err := s.db.QueryRow(`SELECT COUNT(*) FROM page_webhooks WHERE page_id = ?`, pageID).Scan(&n)
	return n, err
}

// CreatePageWebhook stores a new webhook.
func (s *Store) CreatePageWebhook(w *PageWebhook) error {
	w.CreatedAt = now()
	id, err := s.db.insert(s.db, `INSERT INTO page_webhooks (page_id, url, secret, events, enabled, created_at, last_at, last_status, last_error)
		VALUES (?, ?, ?, ?, ?, ?, 0, 0, '')`, w.PageID, w.URL, w.Secret, eventsText(w.Events), b2i(w.Enabled), w.CreatedAt)
	if err != nil {
		return err
	}
	w.ID = id
	return nil
}

// UpdatePageWebhook changes the address, secret, events and switch of a webhook.
func (s *Store) UpdatePageWebhook(w *PageWebhook) error {
	res, err := s.db.Exec(`UPDATE page_webhooks SET url = ?, secret = ?, events = ?, enabled = ? WHERE id = ? AND page_id = ?`,
		w.URL, w.Secret, eventsText(w.Events), b2i(w.Enabled), w.ID, w.PageID)
	if err != nil {
		return err
	}
	if n, _ := res.RowsAffected(); n == 0 {
		// MariaDB/MySQL count only changed rows: check that it exists.
		if _, err := s.PageWebhook(w.PageID, w.ID); err != nil {
			return err
		}
	}
	return nil
}

// DeletePageWebhook removes a webhook.
func (s *Store) DeletePageWebhook(pageID, id int64) error {
	res, err := s.db.Exec(`DELETE FROM page_webhooks WHERE id = ? AND page_id = ?`, id, pageID)
	if err != nil {
		return err
	}
	if n, _ := res.RowsAffected(); n == 0 {
		return ErrNotFound
	}
	return nil
}

// SetPageWebhookResult records the outcome of the latest delivery.
func (s *Store) SetPageWebhookResult(id, at int64, status int, errText string) error {
	if len(errText) > 500 {
		errText = errText[:500]
	}
	_, err := s.db.Exec(`UPDATE page_webhooks SET last_at = ?, last_status = ?, last_error = ? WHERE id = ?`, at, status, errText, id)
	return err
}
